class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD&&window.SW_GEO_SP?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, SUB=CF.sub.SP, $=id=>document.getElementById(id), G=SW_GEO_SP, MU=SWD.munis().filter(m=>D.tx[m]!=null&&D.pop[m]);
    SWD.page({active:'cresc',lv:'SUB',label:'Crescimento'});
    $('vstamp').innerHTML=SWD.stamp('pop'); $('src').innerHTML=SWD.srcLine(['pop']); $('rgl').textContent=SUB.regionLabel;
    const st={sel:SWD.q.get('mu')||CF.sub.SP.ficha,hov:null,q:'',r:''};
    $('reg').innerHTML=`<option value="">Todas</option>`+[...new Set(MU.map(m=>G.meta[m][1]))].sort().map(r=>`<option>${r}</option>`).join('');
    $('reg').onchange=e=>{st.r=e.target.value;plot();side()};
    SWD.searchBox($('search'),`Buscar entre ${MU.length} ${SUB.units}`,v=>{const q=SWD.norm(v.trim()); if(!q) return; const m=MU.filter(k=>SWD.norm(G.meta[k][0]).startsWith(q)).sort((a,b)=>D.pop[b]-D.pop[a])[0]; if(m){st.sel=m;plot();side()}});
    const W=900,H=540,L=44,R=16,T=20,B=36, lx0=Math.log10(500), lx1=Math.log10(2e7), y0=-3, y1=5;
    const X=v=>L+(Math.log10(v)-lx0)/(lx1-lx0)*(W-L-R), Y=v=>T+(y1-Math.max(y0,Math.min(y1,v)))/(y1-y0)*(H-T-B);
    const keep=m=>!st.r||G.meta[m][1]===st.r;
    const big=MU.slice().sort((a,b)=>D.pop[b]-D.pop[a]).slice(0,4);
    const plot=()=>{ let g='';
      [-3,-2,-1,0,1,2,3,4,5].forEach(v=>g+=`<line class="${v===0?'zero':'gl'}" x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}"/><text x="${L-8}" y="${Y(v)+4}" text-anchor="end">${v>0?'+':v<0?'−':''}${Math.abs(v)}%</text>`);
      [1e3,1e4,1e5,1e6,1e7].forEach(v=>g+=`<line class="gl" x1="${X(v)}" x2="${X(v)}" y1="${T}" y2="${H-B}"/><text x="${X(v)}" y="${H-12}" text-anchor="middle">${v>=1e6?SWD.num(v/1e6,0)+' mi':SWD.num(v/1e3,0)+' mil'}</text>`);
      g+=`<text class="qt" x="${W-R-6}" y="${Y(0)-10}" text-anchor="end">Cresceu ▲</text><text class="qt" x="${W-R-6}" y="${Y(0)+20}" text-anchor="end">Encolheu ▼</text>`;
      g+=MU.map(m=>`<circle class="pt ${D.tx[m]<0?'neg':'pos'}${keep(m)?'':' out'}" cx="${X(D.pop[m]).toFixed(1)}" cy="${Y(D.tx[m]).toFixed(1)}" r="3.2"/>`).join('');
      const s=st.hov||st.sel;
      g+=big.filter(m=>m!==s&&keep(m)).map(m=>`<text class="lab" x="${X(D.pop[m])-8}" y="${Y(D.tx[m])-8}" text-anchor="end" style="font-weight:500;fill:var(--sub)">${SWD.name(m)}</text>`).join('');
      if(s) g+=`<circle class="ptsel" cx="${X(D.pop[s])}" cy="${Y(D.tx[s])}" r="6"/><text class="lab" x="${X(D.pop[s])+(X(D.pop[s])>W-200?-10:10)}" y="${Y(D.tx[s])-10}" text-anchor="${X(D.pop[s])>W-200?'end':'start'}">${SWD.name(s)}</text>`;
      $('sc').innerHTML=`<svg class="sc" viewBox="0 0 ${W} ${H}" role="img" aria-label="Dispersão dos ${MU.length} municípios: população e crescimento ao ano">${g}<text x="${L}" y="12" style="font-weight:600;fill:var(--sub)">% ao ano</text><rect class="hit" x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}" fill="transparent"/></svg>`;
      const svg=$('sc').querySelector('svg'), hit=svg.querySelector('.hit');
      const near=e=>{const r=svg.getBoundingClientRect(), px=(e.clientX-r.left)/r.width*W, py=(e.clientY-r.top)/r.height*H; let b=null,bd=144; for(const m of MU){ if(!keep(m)) continue; const dx=X(D.pop[m])-px, dy=Y(D.tx[m])-py, d=dx*dx+dy*dy; if(d<bd){bd=d;b=m} } return b;};
      hit.onmousemove=e=>{const m=near(e); if(m!==st.hov){st.hov=m;plot();side()}};
      hit.onmouseleave=()=>{st.hov=null;plot();side()};
      hit.onclick=e=>{const m=near(e); if(m){st.sel=m;st.hov=null;plot();side()}};
    };
    $('lg').innerHTML=`<span><i style="background:var(--d5);border-radius:50%"></i>Cresceu</span><span><i style="background:var(--d0);border-radius:50%"></i>Encolheu</span><span><i style="background:var(--flag);border-radius:50%"></i>Selecionado</span><span style="color:var(--faint)">Eixo da população em escala logarítmica. Valores acima de +5% ou abaixo de −3% ficam na borda.</span>`;
    const side=()=>{ const vis=MU.filter(keep), up=vis.filter(m=>D.tx[m]>0).length, dn=vis.filter(m=>D.tx[m]<0).length, u=st.hov||st.sel;
      $('cnt').innerHTML=`<div><small>Cresceram</small><b>${up}</b></div><div><small>Encolheram</small><b>${dn}</b></div><div><small>${st.r?'Na região':'No estado'}</small><b>${vis.length}</b></div>`;
      $('card').innerHTML=`<div class="card" aria-live="polite"><div class="meta">${G.meta[u][1]}</div><div class="row1"><div class="nm">${SWD.name(u)}</div><div class="big">${SWD.sgn(D.tx[u],2)}<small>% ao ano</small></div></div>
        <div class="facts"><div class="fact"><span>Censo 2010</span><b>${SWD.int(D.pop10[u])}</b></div><div class="fact"><span>Censo 2022</span><b>${SWD.int(D.pop[u])}</b></div><div class="fact"><span>Média de ${SUB.name}</span><b>${SWD.sgn(D.tx.SP,2,'% ao ano')}</b></div></div>
        <div class="line" style="font-size:15px"><a href="${SWD.href('SUB','ficha','m='+u)}">Abrir a ficha de ${SWD.name(u)} →</a></div></div>`;
      const top=(arr,t)=>`<div><h3 class="sec-h" style="margin-bottom:6px">${t}</h3><div class="fs" style="gap:0">${arr.map(m=>`<button type="button" data-m="${m}" class="${m===st.sel?'on':''}" style="padding:8px 12px;grid-template-columns:minmax(0,1fr) auto;display:grid;gap:10px"><span style="font-size:15px">${SWD.name(m)}</span><span style="font-size:15px;font-weight:600">${SWD.sgn(D.tx[m],2,'%')}</span></button>`).join('')}</div></div>`;
      const s=vis.slice().sort((a,b)=>D.tx[b]-D.tx[a]);
      $('lists').innerHTML=top(s.slice(0,5),'Mais cresceram')+top(s.slice(-5).reverse(),'Mais encolheram');
      $('lists').onclick=e=>{const b=e.target.closest('button[data-m]'); if(b){st.sel=b.dataset.m;plot();side()}};
    };
    plot(); side();
  }
  renderVals(){ return {}; }
}
